<?php

/* @autogenerated */
declare(strict_types=1);

use PHPUnit\Framework\TestCase;
use Civi\Lughauth\Shared\Security\Identity;
use Civi\Lughauth\Shared\Security\AuthenticationContext;

final class AuthenticationContextUnitTest extends TestCase
{
    public function testAnonymousFactoryBuildsDefaults(): void
    {
        $context = AuthenticationContext::anonymous();

        $this->assertSame(AuthenticationContext::LEVEL_ANONYMOUS, $context->getLevel());
        $this->assertFalse($context->isMfa());
        $this->assertFalse($context->isRememberMe());
        $this->assertFalse($context->isImpersonated());
        $this->assertFalse($context->isSecureTransport());
        $this->assertSame('', $context->getSessionId());
        $this->assertNull($context->getAuthenticationMethod());
        $this->assertNull($context->getAuthenticatedActor());
        $this->assertNull($context->getEffectiveActor());
    }

    public function testConstructorAndGettersReturnProvidedValues(): void
    {
        $actor = Identity::from(
            anonymous: false,
            authScope: Identity::AUTH_SCOPE_BOTH,
            id: 'u1',
            name: 'User 1',
            token: 'tkn',
            issuer: 'issuer',
            tenant: 'tenant',
            roles: ['admin'],
            groups: ['g1'],
            claims: ['k' => 'v'],
            scope: 'read',
            email: 'u1@example.org'
        );
        $at = new \DateTimeImmutable('2024-01-01T00:00:00+00:00');
        $age = new \DateInterval('PT5S');

        $context = new AuthenticationContext(
            level: AuthenticationContext::LEVEL_MFA,
            mfa: true,
            rememberMe: true,
            impersonated: true,
            secureTransport: true,
            authenticatedAt: $at,
            authenticationAge: $age,
            authenticationMethod: 'pwd+otp',
            sessionId: 'sess-1',
            authenticatedActor: $actor,
            effectiveActor: $actor
        );

        $this->assertSame(AuthenticationContext::LEVEL_MFA, $context->getLevel());
        $this->assertTrue($context->isMfa());
        $this->assertTrue($context->isRememberMe());
        $this->assertTrue($context->isImpersonated());
        $this->assertTrue($context->isSecureTransport());
        $this->assertSame($at, $context->getAuthenticatedAt());
        $this->assertSame($age, $context->getAuthenticationAge());
        $this->assertSame('pwd+otp', $context->getAuthenticationMethod());
        $this->assertSame('sess-1', $context->getSessionId());
        $this->assertSame($actor, $context->getAuthenticatedActor());
        $this->assertSame($actor, $context->getEffectiveActor());
    }

    public function testJsonSerializeContainsExpectedShape(): void
    {
        $at = new \DateTimeImmutable('-2 seconds');
        $context = new AuthenticationContext(
            level: AuthenticationContext::LEVEL_PASSWORD,
            mfa: false,
            rememberMe: false,
            impersonated: false,
            secureTransport: true,
            authenticatedAt: $at,
            authenticationMethod: null,
            sessionId: 's-1'
        );

        $json = $context->jsonSerialize();

        $this->assertSame(AuthenticationContext::LEVEL_PASSWORD, $json['level']);
        $this->assertSame(true, $json['secureTransport']);
        $this->assertSame('', $json['authenticationMethod']);
        $this->assertSame('s-1', $json['sessionId']);
        $this->assertIsString($json['authenticatedAt']);
        $this->assertIsInt($json['authenticationAge']);
        $this->assertGreaterThanOrEqual(0, $json['authenticationAge']);
    }
}
